3	import type { StackResource } from '@aws-sdk/client-cloudformation';
4	import { GetBucketPolicyCommand, PutBucketPolicyCommand } from '@aws-sdk/client-s3';
5	import { readConfig } from '../utils';
6	import { createInvalidation, getStackByTag, printConfigNotFound, printStackNotFound, s3Client } from './utils';
7	
8	export interface UpdateBucketPoliciesOptions {
9	  file?: string;
10	  dryrun?: boolean;
11	}
12	
13	interface Policy {
14	  Version?: string;
15	  Statement?: PolicyStatement[];
16	}
17	
18	interface PolicyStatement {
19	  Effect?: string;
20	  Principal?: { AWS: string };
21	  Action?: string | string[];
22	  Resource?: string | string[];
23	}
24	
25	/**
26	 * The AWS "update-bucket-policies" command adds necessary policy statements to S3 bucket policy documents.
27	 *
28	 * This is necessary for Medplum deployments outside of the us-east-1 region.
29	 *
30	 * @param tag - The Medplum stack tag.
31	 * @param options - The update options.
32	 */
33	export async function updateBucketPoliciesCommand(tag: string, options: UpdateBucketPoliciesOptions): Promise<void> {
34	  const config = readConfig(tag, options);
35	  if (!config) {
36	    printConfigNotFound(tag, options);
37	    throw new Error(`Config not found: ${tag}`);
38	  }
39	
40	  const details = await getStackByTag(tag);
41	  if (!details) {
42	    await printStackNotFound(tag);
43	    throw new Error(`Stack not found: ${tag}`);
44	  }
45	
46	  await updateBucketPolicy('App', details.appBucket, details.appDistribution, details.appOriginAccessIdentity, options);
47	
48	  await updateBucketPolicy(
49	    'Storage',
50	    details.storageBucket,
51	    details.storageDistribution,
52	    details.storageOriginAccessIdentity,
53	    options
54	  );
55	
56	  console.log('Done');
57	}
58	
59	export async function updateBucketPolicy(
60	  friendlyName: string,
61	  bucketResource: StackResource | undefined,
62	  distributionResource: StackResource | undefined,
63	  oaiResource: StackResource | undefined,
64	  options: UpdateBucketPoliciesOptions
65	): Promise<void> {
66	  if (!bucketResource?.PhysicalResourceId) {
67	    throw new Error(`${friendlyName} bucket not found`);
68	  }
69	
70	  if (!distributionResource?.PhysicalResourceId) {
71	    throw new Error(`${friendlyName} distribution not found`);
72	  }
73	
74	  if (!oaiResource?.PhysicalResourceId) {
75	    throw new Error(`${friendlyName} OAI not found`);
76	  }
77	
78	  const bucketName = bucketResource.PhysicalResourceId;
79	  const oaiId = oaiResource.PhysicalResourceId;
80	  const bucketPolicy = await getPolicy(bucketName);
81	  if (policyHasStatement(bucketPolicy, bucketName, oaiId)) {
82	    throw new Error(`${friendlyName} bucket already has policy statement`);
83	  }
84	
85	  addPolicyStatement(bucketPolicy, bucketName, oaiId);
86	  console.log(`${friendlyName} bucket policy:`);
87	  console.log(JSON.stringify(bucketPolicy, undefined, 2));
88	
89	  if (options.dryrun) {
90	    console.log('Dry run - skipping updates');
91	  } else {
92	    // Apply the updated policy
93	    console.log('Updating bucket policy...');
94	    await setPolicy(bucketName, bucketPolicy);
95	    console.log('Bucket policy updated');
96	
97	    // Create a CloudFront invalidation to clear any cached responses
98	    console.log('Creating CloudFront invalidation...');
99	    await createInvalidation(distributionResource.PhysicalResourceId);
100	    console.log('CloudFront invalidation created');
101	
102	    console.log(`${friendlyName} bucket policy updated`);
103	  }
104	}
105	
106	async function getPolicy(bucketName: string): Promise<Policy> {
107	  const policyResponse = await s3Client.send(
108	    new GetBucketPolicyCommand({
109	      Bucket: bucketName,
110	    })
111	  );
112	  return JSON.parse(policyResponse.Policy ?? '{}') as Policy;
113	}
114	
115	async function setPolicy(bucketName: string, policy: Policy): Promise<void> {
116	  await s3Client.send(
117	    new PutBucketPolicyCommand({
118	      Bucket: bucketName,
119	      Policy: JSON.stringify(policy),
120	    })
121	  );
122	}
123	
124	function policyHasStatement(policy: Policy, bucketName: string, oaiId: string): boolean {
125	  return !!policy?.Statement?.some((s: PolicyStatement) => {
126	    return (
127	      s?.Effect === 'Allow' &&
128	      s?.Principal?.AWS === `arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity ${oaiId}` &&
129	      Array.isArray(s?.Action) &&
130	      s?.Action?.includes('s3:GetObject*') &&
131	      s?.Action?.includes('s3:GetBucket*') &&
132	      s?.Action?.includes('s3:List*') &&
133	      Array.isArray(s?.Resource) &&
134	      s?.Resource?.includes(`arn:aws:s3:::${bucketName}`) &&
135	      s?.Resource?.includes(`arn:aws:s3:::${bucketName}/*`)
136	    );
137	  });
138	}
139	
140	function addPolicyStatement(policy: Policy, bucketName: string, oaiId: string): void {
141	  if (!policy.Version) {
142	    policy.Version = '2012-10-17';
143	  }
144	
145	  if (!policy.Statement) {
146	    policy.Statement = [];
147	  }
148	
149	  policy.Statement.push({
150	    Effect: 'Allow',
151	    Principal: {
152	      AWS: `arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity ${oaiId}`,
153	    },
154	    Action: ['s3:GetObject*', 's3:GetBucket*', 's3:List*'],
155	    Resource: [`arn:aws:s3:::${bucketName}`, `arn:aws:s3:::${bucketName}/*`],
156	  });
157	}
